const fs = require('fs');

const n = Number(fs.readFileSync(0, 'utf8').trim());
const dp = new Int32Array(n + 1);

for (let i = 1; i <= n; i++) {
  let x = i;
  let best = Infinity;

  while (x > 0) {
    const digit = x % 10;
    if (digit > 0) best = Math.min(best, dp[i - digit]);
    x = Math.floor(x / 10);
  }

  dp[i] = best + 1;
}

console.log(dp[n]);
